import{_ as t,c as r,o as a,a5 as o}from"./chunks/framework.DuCYAsAJ.js";const h=JSON.parse('{"title":"Count 写链路与事件分发","description":"","frontmatter":{"title":"Count 写链路与事件分发","date":"2026-05-24T00:00:00.000Z","source":"https://app.devin.ai/org/feed/wiki/qiqi776/zfeed?branch=main#5.1","branch":"main","level":1,"order":5.1},"headers":[],"relativePath":"posts/projects/zfeed/05-count-rpc-service/01-count-write-chain-and-event-dispatch.md","filePath":"posts/projects/zfeed/05-count-rpc-service/01-count-write-chain-and-event-dispatch.md","lastUpdated":1779632679000}'),c={name:"posts/projects/zfeed/05-count-rpc-service/01-count-write-chain-and-event-dispatch.md"};function n(i,e,l,p,b,s){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="count-写链路与事件分发" tabindex="-1">Count 写链路与事件分发 <a class="header-anchor" href="#count-写链路与事件分发" aria-label="Permalink to &quot;Count 写链路与事件分发&quot;">​</a></h1><details><summary>相关源文件</summary><ul><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/feed/followlogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/feed/followlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/feed/recommendlogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/feed/recommendlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/feed/userfavoritelogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/feed/userfavoritelogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/feed/userpublishlogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/feed/userpublishlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/event/dispatcher.go" target="_blank" rel="noreferrer">app/rpc/count/internal/event/dispatcher.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/event/dispatcher_test.go" target="_blank" rel="noreferrer">app/rpc/count/internal/event/dispatcher_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/event/strategy/like_strategy.go" target="_blank" rel="noreferrer">app/rpc/count/internal/event/strategy/like_strategy.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/count_operator.go" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/count_operator.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/declogic.go" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/declogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/repositories/count_value_repository.go" target="_blank" rel="noreferrer">app/rpc/count/internal/repositories/count_value_repository.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/canal/conf/canal.properties" target="_blank" rel="noreferrer">deploy/canal/conf/canal.properties</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/canal/conf/count/instance.properties" target="_blank" rel="noreferrer">deploy/canal/conf/count/instance.properties</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/canal/reset-and-start.sh" target="_blank" rel="noreferrer">deploy/canal/reset-and-start.sh</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/mysql/my.cnf" target="_blank" rel="noreferrer">deploy/mysql/my.cnf</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/mysql/mysql-reseed.sh" target="_blank" rel="noreferrer">deploy/mysql/mysql-reseed.sh</a></li></ul></details><p><code>count-rpc</code> 服务实现了一个高性能异步计数系统。zfeed 不会在用户动作过程中同步更新计数器，因为那会引入额外延迟和数据库竞争；它通过 Canal 监听 MySQL binlog 实现 CDC（Change Data Capture）。本文说明写链路：从初始数据库变更，到分片计数递增和缓存失效。</p><h2 id="架构概览" tabindex="-1">架构概览 <a class="header-anchor" href="#架构概览" aria-label="Permalink to &quot;架构概览&quot;">​</a></h2><p>Count 写链路是一条事件驱动流水线，用于保障社交指标（点赞、评论、收藏、关注）的最终一致性。</p><h3 id="数据流-从-mysql-到计数存储" tabindex="-1">数据流：从 MySQL 到计数存储 <a class="header-anchor" href="#数据流-从-mysql-到计数存储" aria-label="Permalink to &quot;数据流：从 MySQL 到计数存储&quot;">​</a></h3><ol><li>源变更：用户执行动作（例如点赞内容），向 <code>zfeed_like</code> 插入一行数据。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/event/strategy/like_strategy.go#L13-L13" target="_blank" rel="noreferrer">app/rpc/count/internal/event/strategy/like_strategy.go#13</a></li><li>Canal 捕获：Canal 监听 MySQL binlog（配置为 <code>ROW</code> 格式），<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/mysql/my.cnf#L4-L5" target="_blank" rel="noreferrer">deploy/mysql/my.cnf#4-5</a> 并过滤相关互动表。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/canal/conf/count/instance.properties#L18-L18" target="_blank" rel="noreferrer">deploy/canal/conf/count/instance.properties#18</a></li><li>Kafka 分发：Canal 将变更事件发布到 <code>zfeed-count-canal</code> Kafka topic。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/canal/conf/count/instance.properties#L20-L20" target="_blank" rel="noreferrer">deploy/canal/conf/count/instance.properties#20</a></li><li>Dispatcher 处理：<code>Dispatcher</code> 消费事件、做幂等去重，并路由到 <code>TableStrategy</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/event/dispatcher.go#L46-L50" target="_blank" rel="noreferrer">app/rpc/count/internal/event/dispatcher.go#46-50</a></li><li>原子更新：<code>CountOperator</code> 将 delta 应用到 <code>zfeed_count_value</code> 表。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/event/dispatcher.go#L78-L86" target="_blank" rel="noreferrer">app/rpc/count/internal/event/dispatcher.go#78-86</a></li><li>热度计分：如果目标是内容项，<code>Dispatcher</code> 会更新分片 Redis bucket，以影响热门 Feed 排序。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/event/dispatcher.go#L124-L154" target="_blank" rel="noreferrer">app/rpc/count/internal/event/dispatcher.go#124-154</a></li></ol><h3 id="代码实体映射" tabindex="-1">代码实体映射 <a class="header-anchor" href="#代码实体映射" aria-label="Permalink to &quot;代码实体映射&quot;">​</a></h3><p>下图把逻辑系统组件映射到具体实现类和文件。</p><p>自然语言到代码实体映射</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/event/dispatcher.go#L22-L44" target="_blank" rel="noreferrer">app/rpc/count/internal/event/dispatcher.go#22-44</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/count_operator.go#L14-L30" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/count_operator.go#14-30</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/canal/conf/count/instance.properties#L18-L22" target="_blank" rel="noreferrer">deploy/canal/conf/count/instance.properties#18-22</a></p><h2 id="事件分发与策略" tabindex="-1">事件分发与策略 <a class="header-anchor" href="#事件分发与策略" aria-label="Permalink to &quot;事件分发与策略&quot;">​</a></h2><p><code>Dispatcher</code> 是传入 binlog 事件的中心协调器。它使用策略模式处理不同表结构，避免主分发逻辑过度膨胀。</p><h3 id="dispatcher-逻辑" tabindex="-1">Dispatcher 逻辑 <a class="header-anchor" href="#dispatcher-逻辑" aria-label="Permalink to &quot;Dispatcher 逻辑&quot;">​</a></h3><p><code>Dispatcher.Dispatch</code> 函数执行以下步骤：</p><ol><li>策略查找：根据 <code>ChangeEvent</code> 中的表名获取对应 <code>TableStrategy</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/event/dispatcher.go#L47-L50" target="_blank" rel="noreferrer">app/rpc/count/internal/event/dispatcher.go#47-50</a></li><li>更新提取：策略解析 <code>Current</code> 和 <code>Previous</code> 数据 map，以确定计数 delta（例如 INSERT 为 +1，DELETE 为 -1）。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/event/strategy/like_strategy.go#L37-L53" target="_blank" rel="noreferrer">app/rpc/count/internal/event/strategy/like_strategy.go#37-53</a></li><li>幂等去重：应用变更前，尝试将 <code>EventID</code> 插入 <code>zfeed_mq_consume_dedup</code> 表。如果 ID 已存在，则跳过事件，避免重复计数。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/event/dispatcher.go#L66-L74" target="_blank" rel="noreferrer">app/rpc/count/internal/event/dispatcher.go#66-74</a></li><li>事务执行：计数表更新和去重表写入包裹在同一个数据库事务中。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/event/dispatcher.go#L65-L92" target="_blank" rel="noreferrer">app/rpc/count/internal/event/dispatcher.go#65-92</a></li></ol><h3 id="表策略" tabindex="-1">表策略 <a class="header-anchor" href="#表策略" aria-label="Permalink to &quot;表策略&quot;">​</a></h3><p>每类互动都有专门策略，例如 <code>likeStrategy</code>。这些策略负责：</p><ul><li>过滤：忽略不影响计数的事件，例如特定 bucket 只追踪内容点赞时，对评论点赞事件进行忽略。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/event/strategy/like_strategy.go#L64-L78" target="_blank" rel="noreferrer">app/rpc/count/internal/event/strategy/like_strategy.go#64-78</a></li><li>状态转换：将状态变化（例如 <code>zfeed_like</code> 中的 <code>status: 10</code> 到 <code>status: 20</code>）映射为 delta。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/event/strategy/like_strategy.go#L47-L50" target="_blank" rel="noreferrer">app/rpc/count/internal/event/strategy/like_strategy.go#47-50</a></li></ul><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/event/dispatcher.go#L46-L112" target="_blank" rel="noreferrer">app/rpc/count/internal/event/dispatcher.go#46-112</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/event/strategy/like_strategy.go#L25-L62" target="_blank" rel="noreferrer">app/rpc/count/internal/event/strategy/like_strategy.go#25-62</a></p><h2 id="countoperator-与原子更新" tabindex="-1">CountOperator 与原子更新 <a class="header-anchor" href="#countoperator-与原子更新" aria-label="Permalink to &quot;CountOperator 与原子更新&quot;">​</a></h2><p><code>CountOperator</code> 负责实际修改计数记录。它会根据仓储实现使用乐观版本控制和悲观锁，确保高并发下的正确性。</p><h3 id="applydelta-流程" tabindex="-1">ApplyDelta 流程 <a class="header-anchor" href="#applydelta-流程" aria-label="Permalink to &quot;ApplyDelta 流程&quot;">​</a></h3><p>调用 <code>ApplyDeltaWithRepoNoCache</code> 时，它会与 <code>CountValueRepository</code> 交互。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/count_operator.go#L65-L82" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/count_operator.go#65-82</a></p><ol><li>加锁：仓储使用 <code>SELECT ... FOR UPDATE</code>（<code>clause.Locking{Strength: &quot;UPDATE&quot;}</code>）锁定 <code>(biz_type, target_type, target_id)</code> 元组对应的特定行。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/repositories/count_value_repository.go#L159-L161" target="_blank" rel="noreferrer">app/rpc/count/internal/repositories/count_value_repository.go#159-161</a></li><li>Upsert 逻辑：如果记录不存在，则创建 <code>version: 1</code> 的新行；如果已存在，则递增 <code>value</code>、递增 <code>version</code>，并更新 <code>updated_at</code> 时间戳。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/repositories/count_value_repository.go#L166-L202" target="_blank" rel="noreferrer">app/rpc/count/internal/repositories/count_value_repository.go#166-202</a></li><li>重试机制：如果出现死锁或锁等待超时，仓储会使用指数退避最多重试 3 次事务。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/repositories/count_value_repository.go#L131-L144" target="_blank" rel="noreferrer">app/rpc/count/internal/repositories/count_value_repository.go#131-144</a></li></ol><h3 id="序列图-count-写链路" tabindex="-1">序列图：Count 写链路 <a class="header-anchor" href="#序列图-count-写链路" aria-label="Permalink to &quot;序列图：Count 写链路&quot;">​</a></h3><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/event/dispatcher.go#L63-L103" target="_blank" rel="noreferrer">app/rpc/count/internal/event/dispatcher.go#63-103</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/repositories/count_value_repository.go#L149-L205" target="_blank" rel="noreferrer">app/rpc/count/internal/repositories/count_value_repository.go#149-205</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/count_operator.go#L84-L97" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/count_operator.go#84-97</a></p><h2 id="热度增量分片" tabindex="-1">热度增量分片 <a class="header-anchor" href="#热度增量分片" aria-label="Permalink to &quot;热度增量分片&quot;">​</a></h2><p>除了更新主计数表，写链路还会为热门内容推荐系统提供输入。</p><h3 id="权重与分片" tabindex="-1">权重与分片 <a class="header-anchor" href="#权重与分片" aria-label="Permalink to &quot;权重与分片&quot;">​</a></h3><ul><li>权重：不同互动对内容“热度”的贡献不同。点赞加 1 分，评论加 3 分，收藏加 4 分。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/event/dispatcher.go#L163-L177" target="_blank" rel="noreferrer">app/rpc/count/internal/event/dispatcher.go#163-177</a></li><li>Redis 分片：为了避免超热门内容造成 Redis hotkey 问题，增量会写入 Redis 中的分片 Hash key。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/event/dispatcher.go#L144-L152" target="_blank" rel="noreferrer">app/rpc/count/internal/event/dispatcher.go#144-152</a></li><li>分片计算：分片由 <code>contentID % HotFeedIncShards</code> 决定。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/event/dispatcher.go#L156-L161" target="_blank" rel="noreferrer">app/rpc/count/internal/event/dispatcher.go#156-161</a></li></ul><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/event/dispatcher.go#L124-L177" target="_blank" rel="noreferrer">app/rpc/count/internal/event/dispatcher.go#124-177</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/common/consts/redis/keys.go" target="_blank" rel="noreferrer">app/rpc/count/internal/common/consts/redis/keys.go</a></p><h2 id="缓存失效策略" tabindex="-1">缓存失效策略 <a class="header-anchor" href="#缓存失效策略" aria-label="Permalink to &quot;缓存失效策略&quot;">​</a></h2><p>为了确保读链路（见第 5.2 节）在计数更新后不会返回旧数据，<code>CountOperator</code> 执行双删策略。</p><ol><li>立即失效：数据库事务提交后，立即删除计数对应的 Redis 缓存 key。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/count_operator.go#L119-L123" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/count_operator.go#119-123</a></li><li>延迟失效：为处理并发读可能从数据库副本读到旧值并重新填充缓存的竞态，会通过 <code>DelayedCacheInvalidator</code> 在短暂延迟（200ms）后调度第二次删除。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/count_operator.go#L125-L131" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/count_operator.go#125-131</a></li></ol><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/count_operator.go#L84-L117" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/count_operator.go#84-117</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/count_operator.go#L21-L21" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/count_operator.go#21</a></p>',36)])])}const u=t(c,[["render",n]]);export{h as __pageData,u as default};
